import{_ as a,o as t,c as n,a5 as s}from"./chunks/framework.pJebtgMf.js";const m=JSON.parse('{"title":"AI 动态 · 2026-08-30","description":"","frontmatter":{"title":"AI 动态 · 2026-08-30","date":"2026-08-30T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-08/ai-news-2026-08-30.md","filePath":"news/2026-08/ai-news-2026-08-30.md","lastUpdated":null}'),r={name:"news/2026-08/ai-news-2026-08-30.md"};function o(l,e,i,c,p,h){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="ai-动态-·-2026-08-30" tabindex="-1">AI 动态 · 2026-08-30 <a class="header-anchor" href="#ai-动态-·-2026-08-30" aria-label="Permalink to &quot;AI 动态 · 2026-08-30&quot;">​</a></h1><blockquote><p>截至 2026-08-30。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="索尼音乐与华纳起诉anthropic-指控其-公然盗用-版权作品训练claude" tabindex="-1">索尼音乐与华纳起诉Anthropic，指控其“公然盗用”版权作品训练Claude <a class="header-anchor" href="#索尼音乐与华纳起诉anthropic-指控其-公然盗用-版权作品训练claude" aria-label="Permalink to &quot;索尼音乐与华纳起诉Anthropic，指控其“公然盗用”版权作品训练Claude&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-30">2026-08-30</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/2d5c6917fa71.jpg" alt="配图"></p><p>索尼音乐出版、华纳查普尔等多家音乐出版商联合起诉Anthropic及其联合创始人，指控其通过非法 torrenting、抓取和下载成千上万受版权保护的作品来训练 Claude 模型，构成“公然的知识产权盗窃”。诉讼要求每件作品最高15万美元赔偿，总金额或达数十亿美元。Anthropic 回应称不同意指控并将积极辩护。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/29/sony-music-warner-sue-anthropic-alleging-a-brazen-campaign-of-intellectual-property-theft/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="meta-推动机器人在数据中心上岗-测试插拔线缆与服务器维护" tabindex="-1">Meta 推动机器人在数据中心上岗，测试插拔线缆与服务器维护 <a class="header-anchor" href="#meta-推动机器人在数据中心上岗-测试插拔线缆与服务器维护" aria-label="Permalink to &quot;Meta 推动机器人在数据中心上岗，测试插拔线缆与服务器维护&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Ars Technica AI</span><time datetime="2026-08-30">2026-08-30</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/a851925872cb.jpg" alt="配图"></p><p>据 WIRED 报道，Meta 正在其数据中心测试机器人执行插拔线缆、重置服务器等技术员工作，以降低人力成本。测试涉及 Watney Robotics、Kinova 和 ABB 等多家供应商的设备，包括用 Kinova Gen3 机械臂进行电源循环操作。此举或使 Meta 在 AI 基础设施支出飙升的同时控制运营开支。</p><p class="news-entry-source"><a href="https://arstechnica.com/ai/2026/08/inside-metas-push-to-put-robots-to-work-in-data-centers/" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="德州州长-abbott-冻结-flock-ai-监控摄像头采购资金" tabindex="-1">德州州长 Abbott 冻结 Flock AI 监控摄像头采购资金 <a class="header-anchor" href="#德州州长-abbott-冻结-flock-ai-监控摄像头采购资金" aria-label="Permalink to &quot;德州州长 Abbott 冻结 Flock AI 监控摄像头采购资金&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-08-30">2026-08-30</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/045e8d5f35d4.jpg" alt="配图"></p><p>在跨党派反对声浪中，德州州长 Greg Abbott 冻结了州政府对 Flock AI 监控摄像头的资金支持。此举恰逢德州论坛报调查披露该州已花费超 3000 万美元采购 Flock 摄像头，资金主要来自保险单附加的 1 美元费用。此前多名警员因滥用该监控系统被停职或面临刑事指控。</p><p class="news-entry-source"><a href="https://www.theverge.com/ai-artificial-intelligence/986541/texas-governor-abbott-flock-cameras" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="腾讯混元-hy4-preview-开源-770b-参数、1m-上下文-聚焦-agent-与-coding" tabindex="-1">腾讯混元 Hy4 preview 开源：770B 参数、1M 上下文，聚焦 Agent 与 Coding <a class="header-anchor" href="#腾讯混元-hy4-preview-开源-770b-参数、1m-上下文-聚焦-agent-与-coding" aria-label="Permalink to &quot;腾讯混元 Hy4 preview 开源：770B 参数、1M 上下文，聚焦 Agent 与 Coding&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-29">2026-08-29</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/26709ec81472.jpg" alt="配图"></p><p>腾讯发布混元 Hy4 preview，总参数 770B、激活 49B，上下文达 1M，重点优化 Agent、代码开发与生产力场景。该模型首次参与自身训练全链路优化，形成递归自我改进闭环，推理吞吐提升 31.8%。已开源并接入 WorkBuddy、CodeBuddy、元宝等产品，API 定价输入 6 元/百万 tokens，输出 18 元/百万 tokens。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/SxrNXURUimQf4hL83ybj?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="google-发布-gemini-omni-1-1-flash-支持-40-秒场景扩展与-4k-超分" tabindex="-1">Google 发布 Gemini Omni 1.1 Flash：支持 40 秒场景扩展与 4K 超分 <a class="header-anchor" href="#google-发布-gemini-omni-1-1-flash-支持-40-秒场景扩展与-4k-超分" aria-label="Permalink to &quot;Google 发布 Gemini Omni 1.1 Flash：支持 40 秒场景扩展与 4K 超分&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-08-29">2026-08-29</time></p><p>Google AI 推出 Gemini Omni 1.1 Flash，新增 40 秒场景扩展、首尾帧控制及 4K 超分辨率能力。该模型面向视频生成场景，强化了长镜头连贯性与画质提升，为创作者提供更灵活的生成控制。</p><p class="news-entry-source"><a href="https://news.google.?oc=5" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="openai-gpt-6-quot-astra-quot-首批输出曝光" tabindex="-1">OpenAI GPT-6 &quot;Astra&quot; 首批输出曝光 <a class="header-anchor" href="#openai-gpt-6-quot-astra-quot-首批输出曝光" aria-label="Permalink to &quot;OpenAI GPT-6 &amp;quot;Astra&amp;quot; 首批输出曝光&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TestingCatalog AI News</span><time datetime="2026-08-29">2026-08-29</time></p><p>TestingCatalog 曝光了 OpenAI GPT-6 代号 &quot;Astra&quot; 模型的首批输出样本。虽然具体能力细节尚未完全公开，但该消息引发社区对下一代 GPT 能力跃迁的广泛猜测，尤其是在多模态与推理方面的潜在突破。</p><p class="news-entry-source"><a href="https://news.google.com/rss/articles/CBMihwFBVV95cUxNYXExbnloZ3c3UUFWd1NXOTRjSUN2MU9ab2ZaQXhRSDVYakF1c3lMYmJucUE5SG9JblZaYXZNX3RIMzlOOWpzVEt5eWw3c1RXUk5ZRFQwSVdlYWpWV0pLUTVMaTBTWFF5QU9kR05OR0MxczBremREU1Rkb2FWUTFlZUtkMmtlNzQ?oc=5" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="gemini-3-7-flash-降价-50-ai-推理成本再下探" tabindex="-1">Gemini 3.7 Flash 降价 50%，AI 推理成本再下探 <a class="header-anchor" href="#gemini-3-7-flash-降价-50-ai-推理成本再下探" aria-label="Permalink to &quot;Gemini 3.7 Flash 降价 50%，AI 推理成本再下探&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">tech-insider.org</span><time datetime="2026-08-30">2026-08-30</time></p><p>Google 将 Gemini 3.7 Flash 的 API 价格下调 50%，进一步降低 AI 应用开发与规模化部署的推理成本。此举延续了头部模型厂商的价格竞争趋势，对依赖大模型 API 的创业公司与开发者构成直接利好。</p><p class="news-entry-source"><a href="https://news.google.com/rss/articles/CBMidEFVX3lxTE5nNDBxeUgzQlJSQl9lMmpvdEtEUlRqSjNWa29xUFRpM0VLUzVVVWxBUEtlZHRUaGhhWThERFNjOVpWcVRfc053Z0RaVUhPajZBd0FUc2U4NHMycThtTmVRRERPeXp1d1lIejNRZjBiTDJZUE1u?oc=5" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="lakr233-vphone-cli-开源虚拟手机命令行工具-今日获-341-星" tabindex="-1">Lakr233/vphone-cli：开源虚拟手机命令行工具，今日获 341 星 <a class="header-anchor" href="#lakr233-vphone-cli-开源虚拟手机命令行工具-今日获-341-星" aria-label="Permalink to &quot;Lakr233/vphone-cli：开源虚拟手机命令行工具，今日获 341 星&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Lakr233/vphone-cli</span><time datetime="2026-08-30">2026-08-30</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/9e38dbdb5d39.png" alt="配图"></p><p>vphone-cli 是一个开源命令行工具，用于管理虚拟手机环境，今日在 GitHub 获得 341 颗新星，总星标近万。该工具为开发者在命令行中创建、配置和操作虚拟设备提供了轻量方案，适合自动化测试与多环境模拟场景。</p><p class="news-entry-source"><a href="https://github.com/Lakr233/vphone-cli" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="crawl4ai-面向-llm-的开源网页爬虫与抓取工具" tabindex="-1">Crawl4AI：面向 LLM 的开源网页爬虫与抓取工具 <a class="header-anchor" href="#crawl4ai-面向-llm-的开源网页爬虫与抓取工具" aria-label="Permalink to &quot;Crawl4AI：面向 LLM 的开源网页爬虫与抓取工具&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">unclecode/crawl4ai</span><time datetime="2026-08-30">2026-08-30</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/63b86457d0ce.png" alt="配图"></p><p>Crawl4AI 是一个专为 LLM 应用设计的开源网页爬虫与抓取库，提供对 AI 友好的结构化输出，方便将网页内容直接用于模型训练或 RAG 流程。项目在 GitHub 上持续活跃，并设有 Discord 社区供开发者交流。</p><p class="news-entry-source"><a href="https://github.com/unclecode/crawl4ai" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="awesome-mcp-servers-mcp-服务器资源合集持续更新" tabindex="-1">awesome-mcp-servers：MCP 服务器资源合集持续更新 <a class="header-anchor" href="#awesome-mcp-servers-mcp-服务器资源合集持续更新" aria-label="Permalink to &quot;awesome-mcp-servers：MCP 服务器资源合集持续更新&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">punkpeye/awesome-mcp-servers</span><time datetime="2026-08-30">2026-08-30</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/730a9096204f.png" alt="配图"></p><p>punkpeye/awesome-mcp-servers 维护了一份精选的 MCP（Model Context Protocol）服务器列表，涵盖各类工具与数据源的接入实现。该仓库是开发者寻找现成 MCP 集成方案的重要参考入口，随生态发展持续更新。</p><p class="news-entry-source"><a href="https://github.com/punkpeye/awesome-mcp-servers" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="calendly-实践-agent-一周半生成-64-个-pr-完成-30-项目重构" tabindex="-1">Calendly 实践：Agent 一周半生成 64 个 PR，完成 30% 项目重构 <a class="header-anchor" href="#calendly-实践-agent-一周半生成-64-个-pr-完成-30-项目重构" aria-label="Permalink to &quot;Calendly 实践：Agent 一周半生成 64 个 PR，完成 30% 项目重构&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-28">2026-08-28</time></p><p>Calendly 公开了其 Agentic Engineering 实践：Agent 已嵌入 Jira-GitHub-CI 生产闭环，自主完成需求拆解、编码、测试与 QA，人类仅负责 Review 与 Merge。IAM 团队一周半内通过 Agent 完成 64 个 PR，覆盖大型解耦项目 30% 工作量。工程瓶颈正从编码能力转向需求定义与人类判断力。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/0yv69MyNwHiwY3IZXPQt?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="snowflake-cortex-agents-扩展-新增-coding-agent-与-skills-package-预览" tabindex="-1">Snowflake Cortex Agents 扩展：新增 Coding Agent 与 Skills Package 预览 <a class="header-anchor" href="#snowflake-cortex-agents-扩展-新增-coding-agent-与-skills-package-预览" aria-label="Permalink to &quot;Snowflake Cortex Agents 扩展：新增 Coding Agent 与 Skills Package 预览&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-28">2026-08-28</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/26841eb12baa.jpg" alt="配图"></p><p>Snowflake 为 Cortex Agents 推出一系列新能力，包括托管式 Coding Agent、Skills Package 技能打包、Agent Toolset 工具复用及 Tool Search 按需发现。同时 Async Agent API 将 GA，支持长任务后台执行与中断恢复。这些能力旨在降低企业大规模运营 AI Agent 的编排与治理复杂度。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/mKFB15kPm6Uw8fNG4Y7e?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><p>（本日无新条目）</p></div>',8)])])}const g=a(r,[["render",o]]);export{m as __pageData,g as default};
